/* Platzhalter TODAY / TOMORROW / THISWEEK in den Testdaten auflösen */
(function(){
  function p(n){ return (n<10?'0':'')+n; }
  function ymd(d){ return d.getFullYear()+'-'+p(d.getMonth()+1)+'-'+p(d.getDate()); }
  var t=new Date(), tm=new Date(t); tm.setDate(t.getDate()+1);
  var mon=new Date(t); mon.setDate(t.getDate()-((t.getDay()+6)%7));
  DEFAULT_DATA.flash.forEach(function(f){ if(f.until.indexOf('TODAY ')===0) f.until=ymd(t)+'T'+f.until.slice(6); });
  (DEFAULT_DATA.ticker||[]).forEach(function(f){ if(f.until.indexOf('TODAY ')===0) f.until=ymd(t)+'T'+f.until.slice(6); });
  DEFAULT_DATA.guests.forEach(function(g){ if(g.date==='TODAY') g.date=ymd(t); if(g.date==='TOMORROW') g.date=ymd(tm); });
  ['menu','menuFiles','menuNotes'].forEach(function(k){ var o=DEFAULT_DATA[k]; if(o && o.THISWEEK){ o[ymd(mon)]=o.THISWEEK; delete o.THISWEEK; } });
})();

